import { Inject, Injectable } from '@nestjs/common';
import type { Knex } from 'knex';
import { KNEX } from '../database/database.module.js';
import { isUniqueViolation } from '../database/unique-violation.js';

const USERS = 'users';
const EMAIL_UNIQUE = 'users_email_unique';

export interface NewUser {
  /** UUID generated by the app. */
  id: string;
  /** Already trimmed and lower-cased. */
  email: string;
  passwordHash: string;
  phone: string | null;
  createdAt: Date;
}

export const InsertUserResult = {
  Created: 'created',
  EmailTaken: 'emailTaken',
} as const;

export type InsertUserResult = (typeof InsertUserResult)[keyof typeof InsertUserResult];

export interface UserCredentials {
  id: string;
  email: string;
  phone: string | null;
  passwordHash: string;
  lockedUntil: Date | null;
}

export interface LoginLockPolicy {
  now: Date;
  maxFailedAttempts: number;
  lockDurationMs: number;
}

interface UserRow {
  id: string;
  email: string;
  phone: string | null;
  password_hash: string;
  failed_login_attempts: number;
  locked_until: Date | null;
}

@Injectable()
export class UsersRepository {
  constructor(@Inject(KNEX) private readonly db: Knex) {}

  async insert(user: NewUser): Promise<InsertUserResult> {
    try {
      await this.db(USERS).insert({
        id: user.id,
        email: user.email,
        password_hash: user.passwordHash,
        phone: user.phone,
        created_at: user.createdAt,
        updated_at: user.createdAt,
      });
      return InsertUserResult.Created;
    } catch (error) {
      if (isUniqueViolation(error, EMAIL_UNIQUE)) return InsertUserResult.EmailTaken;
      throw error;
    }
  }

  async findByEmail(email: string): Promise<UserCredentials | null> {
    const row = await this.db<UserRow>(USERS)
      .where({ email })
      .first('id', 'email', 'phone', 'password_hash', 'locked_until');
    if (!row) return null;
    return {
      id: row.id,
      email: row.email,
      phone: row.phone,
      passwordHash: row.password_hash,
      lockedUntil: row.locked_until,
    };
  }

  // Both login methods lock the user row, so parallel failures are all counted and a right
  // password sees a lock they set while it was being verified.
  async recordFailedLogin(userId: string, policy: LoginLockPolicy): Promise<Date | null> {
    return this.db.transaction(async (trx) => {
      const row = await trx<UserRow>(USERS)
        .where({ id: userId })
        .forUpdate()
        .first('failed_login_attempts', 'locked_until');
      if (!row) return null;
      if (row.locked_until && row.locked_until > policy.now) return row.locked_until;

      const attempts = row.failed_login_attempts + 1;
      const lockUntil =
        attempts >= policy.maxFailedAttempts
          ? new Date(policy.now.getTime() + policy.lockDurationMs)
          : null;
      await trx(USERS)
        .where({ id: userId })
        .update({
          failed_login_attempts: lockUntil ? 0 : attempts,
          locked_until: lockUntil,
          updated_at: policy.now,
        });
      return lockUntil;
    });
  }

  async recordSuccessfulLogin(userId: string, now: Date): Promise<Date | null> {
    return this.db.transaction(async (trx) => {
      const row = await trx<UserRow>(USERS)
        .where({ id: userId })
        .forUpdate()
        .first('failed_login_attempts', 'locked_until');
      if (!row) return null;
      if (row.locked_until && row.locked_until > now) return row.locked_until;

      if (row.failed_login_attempts > 0 || row.locked_until) {
        await trx(USERS)
          .where({ id: userId })
          .update({ failed_login_attempts: 0, locked_until: null, updated_at: now });
      }
      return null;
    });
  }
}
